"""Writes humanitas_frontend/src/lib/appRoutes.generated.ts from AppRoutes.tsx (the pages the Ctrl+K search may offer).
Run from Humanitas-ERP after adding or removing a route."""
import pathlib, re
fe = pathlib.Path(__file__).resolve().parent.parent / 'humanitas_frontend' / 'src'
src = (fe / 'AppRoutes.tsx').read_text(encoding='utf-8')
paths = sorted({p for p in re.findall(r'path="([^"]+)"', src) if p != '*'})
body = ''.join(f"  '{p}',\n" for p in paths)
(fe / 'lib' / 'appRoutes.generated.ts').write_text(
    '// Generated by scripts/gen_app_routes.py from AppRoutes.tsx. Do not edit by hand.\n'
    '/** Every page the router has; the Ctrl+K search offers only these. */\n'
    f'export const APP_ROUTES: string[] = [\n{body}];\n', encoding='utf-8')
print(f'appRoutes.generated.ts: {len(paths)} routes')
